const body = $input.first().json;
// n8n webhook enveloppe la payload dans body.body
const payload = body.body || body;
const fields = (payload.data && payload.data.fields) ? payload.data.fields : (payload.fields || []);
const errors = [];

// Trouve un champ par sous-chaine dans le label (ignore la casse)
function getField(substr) {
  return fields.find(f => f.label && f.label.toLowerCase().includes(substr.toLowerCase()));
}

// Pour DROPDOWN/CHECKBOXES, Tally envoie des UUIDs dans value[]
// Il faut resoudre vers le texte via le tableau options[]
function resolveValue(field) {
  if (!field) return null;
  const v = field.value;
  if ((field.type === 'DROPDOWN' || field.type === 'CHECKBOXES' || field.type === 'MULTIPLE_CHOICE') && Array.isArray(v) && field.options) {
    const texts = v.map(id => {
      const opt = field.options.find(o => o.id === id);
      return opt ? opt.text : id;
    }).filter(Boolean);
    return field.type === 'DROPDOWN' ? (texts[0] || '') : texts.join(', ');
  }
  return v;
}

const matiere = String(resolveValue(getField('atière') || getField('atiere')) || '').trim();
const niveau = String(resolveValue(getField('iveau')) || '').trim();
const notion = String(resolveValue(getField('otion')) || '').trim();
const profNom = String(resolveValue(getField('om du professeur')) || '').trim();
const profEmail = String(resolveValue(getField('mail')) || '').trim();
const nbCartesRaw = resolveValue(getField('ombre de cartes'));
const nbCartes = parseInt(String(nbCartesRaw || '15')) || 15;
const instructions = String(resolveValue(getField('nstructions')) || '').trim();

// FILE_UPLOAD : value = [{url, name, mimeType, size}]
const fichierField = getField('ichier PDF') || getField('ichier pdf') || getField('PDF');
const fichierRaw = fichierField ? fichierField.value : null;
let pdfUrl = '';
let pdfFilename = 'cours.pdf';
if (Array.isArray(fichierRaw) && fichierRaw.length > 0 && fichierRaw[0].url) {
  pdfUrl = fichierRaw[0].url;
  pdfFilename = fichierRaw[0].name || 'cours.pdf';
}

if (!matiere) errors.push('Matière manquante');
if (!niveau) errors.push('Niveau manquant');
if (!notion) errors.push('Notion manquante');
if (!profEmail || !profEmail.includes('@')) errors.push('Email invalide');
if (!pdfUrl) errors.push('Fichier PDF manquant');

const id = 'box_' + Math.random().toString(36).substring(2, 10);
const codeSup = 'SUP-' + Math.random().toString(36).substring(2, 10).toUpperCase();

return [{ json: {
  valid: errors.length === 0,
  errors: errors.join(', '),
  matiere,
  niveau,
  notion,
  prof_nom: profNom,
  prof_email: profEmail,
  nb_cartes: nbCartes,
  instructions,
  pdf_url: pdfUrl,
  pdf_filename: pdfFilename,
  id,
  code_suppression: codeSup,
  date_creation: new Date().toISOString().split('T')[0]
} }];

const prevData = $('Parser Tally').first().json;
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Pdf = binaryData.toString('base64');

const prompt = `Tu es un assistant pédagogique pour un collège français. Tu crées des fiches de révision (flashcards) au format question/réponse à partir du contenu d'un cours.

CONTEXTE :
- Matière : ${prevData.matiere}
- Niveau : ${prevData.niveau}
- Notion/Chapitre : ${prevData.notion}
- Nombre de cartes demandé : ${prevData.nb_cartes}
${prevData.instructions ? '- Instructions du professeur : ' + prevData.instructions : ''}

CONSIGNES :
1. Génère exactement ${prevData.nb_cartes} flashcards question/réponse.
2. Les questions doivent couvrir les points essentiels : définitions, mécanismes, dates, formules, exemples.
3. Les réponses doivent être CONCISES (2-3 phrases maximum) mais COMPLÈTES et EXACTES.
4. Adapte le vocabulaire au niveau ${prevData.niveau} (collège français).
5. Varie les types de questions : "Qu'est-ce que...", "Comment...", "Pourquoi...", "Cite...", "Quelle est la différence entre...".
6. Attribue un niveau de difficulté à chaque carte : "facile", "moyen", ou "difficile".
7. Ne modifie PAS les informations du cours.

IMPORTANT : Réponds UNIQUEMENT avec un JSON valide, sans texte avant ni après :
{
  "cartes": [
    { "numero": 1, "question": "...", "reponse": "...", "difficulte": "facile" }
  ],
  "notes": "Commentaire optionnel si contenu insuffisant"
}`;

const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 4096,
  messages: [{
    role: 'user',
    content: [
      { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64Pdf } },
      { type: 'text', text: prompt }
    ]
  }]
};

return [{ json: { requestBody, ...prevData } }];

const prevData = $('Preparer requete Claude').first().json;
const claudeResponse = $input.first().json;

let content = '';
if (claudeResponse.content && claudeResponse.content[0]) {
  content = claudeResponse.content[0].text || '';
}

let parsed;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Pas de JSON dans la réponse');
  }
} catch (e) {
  return [{ json: { parse_ok: false, error: 'Erreur de parsing : ' + e.message, ...prevData } }];
}

const cartes = parsed.cartes || [];
if (cartes.length === 0) {
  return [{ json: { parse_ok: false, error: 'Aucune carte générée', ...prevData } }];
}

// T-SEC (2026-10-06) : pose explicitement revue_carte_par_carte: false a la
// generation. Seul box-select-confirm (relecture carte par carte) le passe a
// true - box-validate (validation en bloc) ne le pose jamais. 'type' n'est PAS
// pose ici : ce workflow genere des jeux BOX ordinaires, jamais Box-FONDA.
const flashcardFile = {
  id: prevData.id,
  matiere: prevData.matiere,
  niveau: prevData.niveau,
  notion: prevData.notion,
  prof_nom: prevData.prof_nom,
  prof_email: prevData.prof_email,
  code_suppression: prevData.code_suppression,
  date_creation: prevData.date_creation,
  nb_cartes: cartes.length,
  source: 'tally',
  source_filename: prevData.pdf_filename || 'cours.pdf',
  cartes,
  revue_carte_par_carte: false
};

const jsonStr = JSON.stringify(flashcardFile, null, 2);
const buffer = Buffer.from(jsonStr, 'utf-8');

return [{
  json: { parse_ok: true, nb_cartes_generees: cartes.length, notes: parsed.notes || '', flashcard_file: flashcardFile, ...prevData },
  binary: { data: await this.helpers.prepareBinaryData(buffer, prevData.id + '.json', 'application/json') }
}];

const prevData = $('Parser reponse Claude').first().json;
const uploadResult = $('Upload Flashcards').first().json;
const driveFileId = uploadResult.id || uploadResult.fileId || '';
const code = prevData.code_suppression;

const cartes = prevData.flashcard_file.cartes || [];
const maxPreview = Math.min(cartes.length, 5);
let cartesHtml = '';
for (let i = 0; i < maxPreview; i++) {
  const c = cartes[i];
  const diff = c.difficulte === 'facile' ? '#16a34a' : c.difficulte === 'moyen' ? '#d97706' : '#dc2626';
  cartesHtml += `<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px;margin:8px 0">
    <div style="color:${diff};font-size:12px;font-weight:bold;margin-bottom:4px">${c.difficulte.toUpperCase()}</div>
    <div style="font-weight:bold;margin-bottom:6px">Q${c.numero}: ${c.question}</div>
    <div style="color:#475569">${c.reponse}</div>
  </div>`;
}
if (cartes.length > maxPreview) {
  cartesHtml += `<p style="color:#64748b;text-align:center">... et ${cartes.length - maxPreview} autres cartes</p>`;
}

const baseUrl = 'https://n8n.srv868991.hstgr.cloud/webhook';
const selectUrl = `${baseUrl}/box-select?file_id=${driveFileId}&code=${encodeURIComponent(code)}`;

const emailHtml = `<h2>BOX - Fiches à valider</h2>
<p><strong>Matière :</strong> ${prevData.matiere}<br>
<strong>Niveau :</strong> ${prevData.niveau}<br>
<strong>Notion :</strong> ${prevData.notion}<br>
<strong>Nombre de cartes :</strong> ${cartes.length}</p>
<hr>
<h3>Aperçu des cartes générées :</h3>
${cartesHtml}
<hr>
<p style="text-align:center;margin:24px 0">
  <a href="${selectUrl}" style="background:#2563eb;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-size:16px;font-weight:bold">&#128203; Relire et choisir les cartes</a>
</p>
<p style="color:#64748b;font-size:12px;text-align:center">Vous pourrez décocher les cartes à exclure avant publication.<br>
Les fiches sélectionnées seront accessibles aux élèves sur <a href="https://ericduchateau.github.io/box/">la page BOX</a>.<br>
Code de suppression (à conserver) : <code>${prevData.id}</code> / <code>${code}</code></p>`;

return [{ json: { prof_email: prevData.prof_email, notion: prevData.notion, email_html: emailHtml } }];
